<?php
/* Use uma única vez localmente e APAGUE este arquivo depois de criar o administrador. */
require __DIR__.'/config.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['nome']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pass=$_POST['senha']??'';if(!$name||!$email||strlen($pass)<12){$error='Informe nome, e-mail válido e senha com pelo menos 12 caracteres.';}else{$s=db()->prepare("INSERT INTO admins(nome,email,senha_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$done=true;}}
?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Criar administrador BY</title><link rel="stylesheet" href="style.css"><body><main class="wrap"><div class="card" style="max-width:500px;margin:50px auto"><h1>Criar administrador</h1><?php if(!empty($done)):?><div class="notice success">Administrador criado. APAGUE o arquivo criar_admin.php agora e entre em admin.php.</div><?php else:?><?php if(isset($error)):?><div class="notice error"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>Nome</label><input name="nome" required></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Senha (mínimo 12 caracteres)</label><input name="senha" type="password" minlength="12" required></div><p><button class="btn">Criar administrador</button></p></form><?php endif?></div></main></body></html>
